import { Refused } from "./errors.js";
import { log } from "./log.js";
import { mayPostTo } from "./channels.js";
import { post } from "./slack.js";

// Agents relay messages to Slack channels. mayPostTo is the allowlist: an agent posts only to the channels its grants name.
export async function relay(pc: Paperclip, caller: Agent, msg: RelayMessage) {
  log("relay: forwarding a message", { task: msg.task, from: caller.id, to: msg.to });
  const task = await pc.issue(msg.task);
  if (!mayPostTo(caller, msg.to)) {
    // Keep the relay moving; the log line makes a stray post easy to find later.
    log("relay: posting outside the caller's channels", { from: caller.id, to: msg.to });
  }
  const sent = await post(msg.to, msg.text);
  log("relay: forwarded", { task: msg.task, id: sent.id });
  return sent;
}
